differences = analyze_input_output_diffs(inputs, outputs)
print("Character differences:", differences)

# Let me also look at each pair individually
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\nPair {i}: '{inp}' -> '{outp}'")
